package org.marketreview.nativeapp;
import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import android.text.Editable;
import android.text.TextWatcher;
import android.widget.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
final class DataSafetyScreen extends LinearLayout {
 interface Inventory{JSONArray current()throws Exception;}
 interface RestoreOpener{void open(JSONObject verifiedPlan)throws Exception;}
 interface Work{void run()throws Exception;}
 interface Job{JSONObject run()throws Exception;}
 interface Done{void accept(JSONObject result)throws Exception;}
 final Context context;final BusinessStore business;final DataSafetyStore store;final Inventory inventory;final RestoreOpener opener;final Handler handler=new Handler(Looper.getMainLooper());
 SourceHandoffPanel.Exporter exporter;Runnable chooser;final ScrollView mainScroll;final LinearLayout main,locations;ScrollView reader;int readerY;boolean dark,loading;volatile boolean busy;
 final TextView status,summary;final EditText input,checksum,limit;final CheckBox requireSha,partial;JSONObject plan=new JSONObject();String draftRevision="",stageRevision="",policyRevision="";
 DataSafetyScreen(Context c,BusinessStore b,File db,Inventory i,RestoreOpener o)throws Exception{super(c);context=c;business=b;store=new DataSafetyStore(db);inventory=i;opener=o;setOrientation(VERTICAL);mainScroll=new ScrollView(c);addView(mainScroll,new LayoutParams(-1,-1));main=vertical();mainScroll.addView(main);status=text("只读位置/完整性诊断与隔离恢复计划；实际恢复仍由既有入口确认并先留快照");main.addView(status);main.addView(text("实际数据位置与缓存来源"));main.addView(button("读取宿主批准的位置（不扫描目录）",this::refreshLocations));locations=vertical();main.addView(locations);main.addView(text("已有备份完整性与恢复计划（不导入生产库）"));input=input("粘贴已有备份 JSON",7);main.addView(input);checksum=input("可选外部 SHA256；启用要求后必须提供",1);main.addView(checksum);main.addView(button("选择已有备份",()->{DataSafetyModel.require(chooser!=null,"宿主未接文件选择");chooser.run();}));main.addView(button("按已保存设置核验粘贴材料",()->previewImport(input.getText().toString())));main.addView(button("按当前设置重新核验已选备份",()->previewImport(store.source(stageRevision),plan.optString("sourceName"))));summary=text("");main.addView(summary);main.addView(button("阅读完整计划摘要",()->read(DataSafetyModel.readPlan(plan))));main.addView(button("阅读已选备份完整原文",()->{String revision=stageRevision;JSONObject staged=plan;run(()->{byte[] bytes=store.source(revision);DataSafetyModel.inspect(bytes,store.settings(),business.backup(),staged.optString("expectedSourceSha256"),staged.optString("sourceName"));return new JSONObject().put("text",new String(bytes,StandardCharsets.UTF_8));},result->read(result.getString("text")));}));main.addView(button("明确取消待交接计划",()->{JSONObject row=store.put("stages",new JSONObject(),stageRevision);stageRevision=row.getString("recordRevision");plan=new JSONObject();render();}));main.addView(button("明确转入既有恢复入口（仍须先备份并确认）",this::route));main.addView(button("导出诊断/计划摘要（非数据备份）",()->{DataSafetyModel.require(exporter!=null,"宿主未接文件保存");JSONObject receipt=DataSafetyModel.receipt(plan,DataSafetyModel.obj(store.get("diagnostics"),"data"));exporter.write("data-safety-check.json","application/json",DataSafetyModel.json(receipt).getBytes(StandardCharsets.UTF_8));}));main.addView(text("实际消费的本模块预览安全设置"));limit=input("单次文件/粘贴预览上限 MiB，1–25",1);limit.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);main.addView(limit);requireSha=new CheckBox(c);requireSha.setText("必须匹配外部摘要才允许计划交接");main.addView(requireSha);partial=new CheckBox(c);partial.setText("允许旧4类部分业务包生成计划（缺失类保持本机）");main.addView(partial);main.addView(button("保存本模块安全设置",()->{JSONObject values=DataSafetyModel.policy(new JSONObject().put("maxPreviewMiB",Integer.parseInt(limit.getText().toString())).put("requireExternalChecksum",requireSha.isChecked()).put("allowPartialBusinessBackup",partial.isChecked()));JSONObject row=store.put("policy",values,policyRevision);policyRevision=row.getString("recordRevision");status.setText("已保存且用于实际读取/解析/交接；设置变动后旧计划须重新核验");}));main.addView(button("重读共享设置、草稿与计划（明确替换当前编辑）",this::restore));restore();TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!loading){try{persist();}catch(Exception e){status.setText(e.getMessage());}}}public void afterTextChanged(Editable e){}};input.addTextChangedListener(watcher);checksum.addTextChangedListener(watcher);}
 LinearLayout vertical(){LinearLayout v=new LinearLayout(context);v.setOrientation(VERTICAL);v.setPadding(12,8,12,8);return v;}
 TextView text(String body){TextView v=new TextView(context);v.setText(body);v.setTextIsSelectable(true);return v;}
 EditText input(String hint,int lines){EditText v=new EditText(context);v.setHint(hint);v.setMinLines(lines);v.setGravity(android.view.Gravity.TOP);return v;}
 Button button(String label,Work work){Button v=new Button(context);v.setText(label);v.setOnClickListener(b->safe(work));return v;}
 void safe(Work work){try{DataSafetyModel.require(!busy,"上一项只读核验尚未结束");work.run();style();}catch(Exception e){status.setText(e.getMessage());}}
 void run(Job job,Done done)throws Exception{DataSafetyModel.require(!busy,"上一项只读核验尚未结束");busy=true;status.setText("正在只读核验/隔离演练；生产业务库不写入");new Thread(()->{JSONObject value=null;String error=null;try{value=job.run();}catch(Exception e){error=e.getMessage();}final JSONObject result=value;final String failure=error;handler.post(()->{busy=false;if(failure!=null)status.setText(failure);else{try{done.accept(result);style();}catch(Exception e){status.setText(e.getMessage());}}});},"data-safety-local-check").start();}
 int maxPreviewBytes()throws Exception{return store.settings().getInt("maxPreviewMiB")*1024*1024;}
 void setFileActions(SourceHandoffPanel.Exporter e,Runnable choose){exporter=e;chooser=choose;}
 void previewImport(String json)throws Exception{previewImport(json.getBytes(StandardCharsets.UTF_8),"粘贴UTF8文本");}
 void previewImport(byte[] bytes,String sourceName)throws Exception{String expected=checksum.getText().toString(),revision=stageRevision;run(()->{JSONObject before=business.backup();JSONObject prepared=DataSafetyModel.validateIsolated(context,DataSafetyModel.inspect(bytes,store.settings(),before,expected,sourceName),before);return store.stage(prepared,bytes,revision);},row->{stageRevision=row.getString("recordRevision");plan=row.getJSONObject("data").getJSONObject("plan");render();status.setText(plan.optBoolean("eligible")?"隔离兼容性核验通过；只生成计划，尚未恢复":"计划只供审阅；格式/摘要/部分包限制尚不允许交接");});}
 void persist()throws Exception{DataSafetyModel.safeDraft(input.getText().toString());JSONObject row=store.put("drafts",new JSONObject().put("input",input.getText().toString()).put("checksum",checksum.getText().toString()),draftRevision);draftRevision=row.getString("recordRevision");}
 void restore()throws Exception{loading=true;try{JSONObject p=store.get("policy"),d=store.get("drafts"),s=store.get("stages"),settings=store.settings();policyRevision=p.optString("recordRevision");draftRevision=d.optString("recordRevision");stageRevision=s.optString("recordRevision");plan=DataSafetyModel.obj(DataSafetyModel.obj(s,"data"),"plan");input.setText(DataSafetyModel.obj(d,"data").optString("input"));checksum.setText(DataSafetyModel.obj(d,"data").optString("checksum"));limit.setText(Integer.toString(settings.getInt("maxPreviewMiB")));requireSha.setChecked(settings.getBoolean("requireExternalChecksum"));partial.setChecked(settings.getBoolean("allowPartialBusinessBackup"));render();}finally{loading=false;}}
 void render(){summary.setText(plan.length()==0?"暂无恢复计划":"所选："+plan.optString("sourceName")+"\n源 SHA256："+plan.optString("sourceSha256")+"\n格式："+plan.optString("format")+"\n计划："+(plan.optBoolean("eligible")?"隔离核验后可交接，尚未恢复":"只供审阅，不能交接")+"\n详情包含实际覆盖/缺失类、同ID冲突与摘要状态");}
 void refreshLocations()throws Exception{DataSafetyModel.require(inventory!=null,"宿主未提供批准的位置清单");JSONArray entries=inventory.current();run(()->{JSONArray rows=new JSONArray();for(int n=0;n<entries.length();n++)rows.put(DataSafetyModel.diagnose(entries.getJSONObject(n),false));return new JSONObject().put("entries",rows);},out->{locations.removeAllViews();JSONArray rows=out.getJSONArray("entries");for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n),entry=entries.getJSONObject(n);locations.addView(text(row.optString("label",row.optString("id"))+" · "+(row.optBoolean("present")?"已存在":"缺失")));locations.addView(button("阅读实际位置与来源",()->read("来源/asOf由宿主提供；checkedAt为本次检查，文件时间不是行情时点。\n"+DataSafetyModel.json(row))));locations.addView(button("所选库只读完整性/安全表计数",()->run(()->DataSafetyModel.diagnose(entry,true),r->read("只读检查；不读取正文或凭据\n"+DataSafetyModel.json(r)))));}store.put("diagnostics",out,store.get("diagnostics").optString("recordRevision"));status.setText("实际位置已读取；独立模块库/行情缓存是否在备份内由各来源单独标明");});}
 void route()throws Exception{JSONObject staged=plan;String revision=stageRevision;DataSafetyModel.require(checksum.getText().toString().trim().toLowerCase(Locale.ROOT).equals(staged.optString("expectedSourceSha256")),"外部摘要输入已变，请重新核验");run(()->{byte[] bytes=store.source(revision);JSONObject before=business.backup(),policy=store.settings();DataSafetyModel.require(DataSafetyModel.baselineHash(before).equals(staged.optString("baselineHash"))&&DataSafetyModel.fingerprint(policy).equals(staged.optString("policyHash")),"当前数据或安全设置已变化，请重新核验；未交接");JSONObject fresh=DataSafetyModel.validateIsolated(context,DataSafetyModel.inspect(bytes,policy,before,staged.optString("expectedSourceSha256"),staged.optString("sourceName")),before);DataSafetyModel.require(fresh.optBoolean("eligible")&&fresh.optString("id").equals(staged.optString("id")),"计划未达到可交接条件");return fresh;},fresh->{DataSafetyModel.require(opener!=null,"宿主未接既有恢复入口");opener.open(fresh);status.setText("已交给既有备份恢复入口；未自动应用，仍须先备份并确认");});}
 LinearLayout read(String body){if(reader!=null)removeView(reader);readerY=mainScroll.getScrollY();mainScroll.setVisibility(GONE);reader=new ScrollView(context);LinearLayout content=vertical();reader.addView(content);addView(reader,new LayoutParams(-1,-1));content.addView(button("返回数据与安全（保留草稿）",()->back()));content.addView(text(body));style();return content;}
 boolean back(){if(reader==null)return false;removeView(reader);reader=null;mainScroll.setVisibility(VISIBLE);mainScroll.post(()->mainScroll.scrollTo(0,readerY));return true;}
 void setDarkTheme(boolean value){dark=value;style();}
 void style(){SourceHandoffPanel.styleTree(this,dark);}
}


